// connError returns ConnectionError(code) but first
// stashes away a public reason to the caller can optionally relay it
// to the peer before hanging up on them. This might help others debug
// their implementations.
// Enhanced to include frame details (type, length, stream ID, flags) for better diagnostics.
func (fr *Framer) connError(code http2.ErrCode, reason string) error {
	// Capture current frame details if available for enhanced error reporting
	var frameDetails string
	if fr.lastFrame != nil {
		fh := fr.lastFrame.Header()
		frameDetails = fmt.Sprintf(" [Frame: type=%s, length=%d, streamID=%d, flags=0x%x]", 
			fh.Type, fh.Length, fh.StreamID, fh.Flags)
	}
	fr.errDetail = errors.New(reason + frameDetails)
	return http2.ConnectionError(code)
}

